page_data_script:
def clean(value):
    return frappe.utils.escape_html(value or "")


def day_month_year(value):
    text = str(value)
    months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    return months[int(text[5:7]) - 1] + " " + str(int(text[8:10])) + ", " + text[:4]


def plain_text(html):
    text = frappe.utils.strip_html(html or "")
    for entity, char in (("&nbsp;", " "), ("&lt;", "<"), ("&gt;", ">"), ("&quot;", '"'), ("&#39;", "'"), ("&amp;", "&")):
        text = text.replace(entity, char)
    return text.strip()


def safe_url(value):
    value = value or ""
    return frappe.utils.escape_html(value) if value.startswith(("/", "https://", "http://")) else ""


def path_segment(value):
    for char, code in (("%", "%25"), ("/", "%2F"), ("?", "%3F"), ("#", "%23"), ("\\", "%5C"), (" ", "%20")):
        value = value.replace(char, code)
    return value


def first_image(html):
    html = html or ""
    start = html.find("<img")
    if start == -1:
        return ""
    src_start = html.find('src="', start)
    if src_start == -1:
        return ""
    src_start += 5
    src_end = html.find('"', src_start)
    if src_end == -1:
        return ""
    return html[src_start:src_end].replace("&amp;", "&")


identifier = frappe.form_dict.username or ""
tab_param = frappe.form_dict.tab or ""

if frappe.session.user == "Guest":
    redirect("/login?redirect=/profile/" + path_segment(identifier) + "/posts")

if not identifier:
    # Builder's editor canvas has no username in the address: show your own posts there.
    user_id = frappe.session.user
else:
    user_id = frappe.db.get_value("User", {"username": identifier}, "name")
    if not user_id and "@" in identifier and frappe.db.exists("User", identifier):
        user_id = identifier
if user_id == "Guest":
    user_id = None

if not user_id:
    data.pp = {"found": False, "not_found": True, "is_other": True, "crumb_name": "Profile", "profile_href": "/profile"}
    data.posts = []
else:
    info = frappe.db.get_value("User", user_id, ["name", "full_name", "username"], as_dict=True)
    username = info.username or info.name.split("@")[0]
    is_own = user_id == frappe.session.user
    tab = tab_param if (is_own and tab_param in ("drafts", "archived")) else "published"
    if identifier and username != identifier:
        redirect("/profile/" + path_segment(username) + "/posts" + ("?tab=" + tab if tab != "published" else ""))

    name = info.full_name or username
    rows = frappe.call("cafe.api.list_profile_posts", user=user_id, limit=0)
    posts = []
    for row in rows:
        text = plain_text(row.get("content"))
        minutes = int(len(text.split()) / 200 + 0.5)
        if minutes < 1:
            minutes = 1
        comments = row.get("comment_count") or 0
        preview = row.get("excerpt") or (text[:140] + "\u2026" if len(text) > 140 else text)
        thumbnail = (
            row.get("cover_image")
            or (row.get("attachment") if row.get("post_type") == "Image" else "")
            or first_image(row.get("content"))
        )
        posts.append({
            "href": "/posts/" + path_segment(row.name),
            "title": clean(row.get("display_title") or row.get("title") or "Untitled"),
            "excerpt": clean(preview),
            "meta": day_month_year(row.creation) + " \u00b7 " + str(minutes) + " min read \u00b7 " + str(comments) + (" comment" if comments == 1 else " comments"),
            "thumbnail": safe_url(thumbnail),
        })
    if not identifier and not posts:
        posts = [{"href": "/posts", "title": "Post title", "excerpt": "A short preview of the post.", "meta": "Sep 18, 2026 \u00b7 1 min read \u00b7 0 comments", "thumbnail": ""}]
    data.pp = {
        "found": True,
        "not_found": False,
        "is_own": is_own,
        "is_other": not is_own,
        "own_flag": "1" if is_own else "",
        "user_id": clean(frappe.session.user) if is_own else "",
        "tab": tab,
        "title": "My Posts" if is_own else "Posts from " + clean(name),
        "crumb_name": clean(name),
        "profile_href": clean("/profile/" + path_segment(username)),
        "published_empty_own": is_own and not posts,
        "published_empty_other": (not is_own) and not posts,
    }
    data.posts = posts
